def text(x):
    if x is None:
        return ''
    if isinstance(x, (list, tuple, set)):
        return ' '.join([text(i) for i in x])
    if isinstance(x, dict):
        return ' '.join([text(k) + ' ' + text(v) for k, v in x.items()])
    return str(x).lower()

def needverb(tt):
    if 'clean' in tt:
        return 'clean'
    if 'heat' in tt:
        return 'heat'
    if 'cool' in tt:
        return 'cool'
    return ''

def hasact(adm, prefix, target, dest):
    for a in adm or []:
        s = text(a)
        if s.startswith(prefix) and (not target or target in s) and (not dest or dest in s):
            return True
    return False

def hook(ctx, nb):
    tt = text(getv(ctx, 'task.task_type', ''))
    target = text(getv(ctx, 'task.target_type', ''))
    dest = text(getv(ctx, 'task.destination_type', ''))
    verb = needverb(tt)
    if not verb:
        nb['transformed'] = True
    act = text(getv(ctx, 'action.final_action', getv(ctx, 'action.normalized', getv(ctx, 'action.raw', ''))))
    obs = text(ctx.get('observation', ''))
    inv = text(getv(ctx, 'world.inventory', ''))
    if verb and target and act.startswith(verb + ' ') and target in act and 'nothing happens' not in obs:
        nb['transformed'] = True
    if verb and target and target in obs and ('you clean' in obs or 'you heat' in obs or 'you cool' in obs):
        nb['transformed'] = True
    pc = getv(ctx, 'world.placed_count', 0)
    try:
        pc = int(pc)
    except Exception:
        pc = 0
    if pc > nb.get('placed_count', 0):
        nb['placed_count'] = pc
    locs = getv(ctx, 'world.placed_locations', [])
    if isinstance(locs, (list, tuple, set)):
        nb['placed_locations'] = [text(x) for x in locs]
    elif locs:
        nb['placed_locations'] = [text(locs)]
    carrying = bool(target and target in inv and 'nothing' not in inv and 'not carrying' not in inv)
    wrong = bool(inv and 'nothing' not in inv and 'not carrying' not in inv and target and not carrying)
    if wrong:
        stage = 'wrong_inventory'
    elif carrying and verb and not nb.get('transformed'):
        stage = 'transform'
    elif carrying and target and dest and hasact(ctx.get('admissible', []), 'put ', target, dest):
        stage = 'put_target'
    elif carrying:
        stage = 'go_destination'
    elif target and hasact(ctx.get('admissible', []), 'take ', target, ''):
        stage = 'take_target'
    else:
        stage = 'find_target'
    nb['stage'] = stage
    nb['target_type'] = target
    nb['destination_type'] = dest
    nb['task_type'] = tt
    nb['required_verb'] = verb
    return None

