def hook(ctx, nb):
    stage = nb.get('stage', '')
    target = nb.get('target_type') or text(getv(ctx, 'task.target_type', ''))
    dest = nb.get('destination_type') or text(getv(ctx, 'task.destination_type', ''))
    verb = nb.get('required_verb') or needverb(nb.get('task_type', ''))
    msg = ''
    if stage == 'wrong_inventory':
        msg = 'Inventory does not match the requested target type. Do not place a wrong item; recover by setting it aside if needed and searching for the target.'
    elif stage == 'transform' and verb:
        msg = 'Before final placement, use the admissible ' + verb + ' action on the carried ' + target + '. Do not put it at the destination yet.'
    elif stage == 'put_target' and target and dest:
        msg = 'You are at the destination with the target. Use the admissible put action for the ' + target + ' in/on the ' + dest + '.'
    elif stage == 'go_destination' and target and dest:
        msg = 'Carry the ' + target + ' to the ' + dest + ' and avoid opening or examining unrelated containers.'
    elif stage == 'take_target' and target:
        msg = 'A requested ' + target + ' is available here. Take it instead of continuing to search unrelated places.'
    elif stage == 'find_target' and target and (getv(ctx, 'predicates.same_action_repeated', False) or getv(ctx, 'predicates.same_observation_repeated', False) or getv(ctx, 'predicates.remaining_steps_low', False)):
        msg = 'Search unopened or unvisited containers for the requested ' + target + ', not for other object types.'
    elif stage == 'find_target' and 'two' in nb.get('task_type', '') and nb.get('placed_count', 0) > 0:
        msg = 'One target is already placed. Leave it there, find another ' + target + ', and use the same destination type.'
    if not msg:
        return None
    key = stage + ':' + msg[:60]
    if nb.get('last_hint') == key:
        return None
    nb['last_hint'] = key
    return {'message': msg}

