    if not carrying and not nb.get('transformed') and verb and target and act.startswith('put ') and target in act:
        return {'kind': 'block_and_prompt', 'message': 'This task requires transforming the target before placement. Use the admissible ' + verb + ' action on the ' + target + ' first, then put it at the destination.'}
