        return None
    if act.startswith('put ') and target in act and dest and dest in act and not hasact(ctx.get('admissible', []), verb, target, ''):
        return {'kind': 'block_and_prompt', 'message': 'Do not place the target yet. First use the admissible ' + verb + ' action, then return to the destination and put it there.'}
    if act.startswith('take ') and target in act and dest and dest in act and nb.get('placed_count', 0) > 0:
        return {'kind': 'block_and_prompt', 'message': 'Do not take back a target that is already placed at the destination. Continue with any remaining target or finish instead.'}
    return None
